import{_ as i,a0 as l,w as o,s as d,ao as r,I as p,x as e,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Linux 文件系統類型導覽 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 文件系統類型導覽 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 文件系統類型導覽 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 文件系統類型導覽 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190820 A guided tour of Linux file system types","title":"Linux 文件系統類型導覽","tag":"201908","desc":""},"relativePath":"201908/20190820 A guided tour of Linux file system types.md","filePath":"[post].md"}'),u={name:"201908/20190820 A guided tour of Linux file system types.md"};function f(c,s,m,h,g,x){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="linux-文件系統類型導覽" tabindex="-1">Linux 文件系統類型導覽 <a class="header-anchor" href="#linux-文件系統類型導覽" aria-label="Permalink to “Linux 文件系統類型導覽”">​</a></h1><blockquote><p>Linux 文件系統多年來在不斷發展，讓我們來看一下文件系統類型。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201908/27/175516vzrp4j4zevcqr66c.jpg" alt=""></p><p>雖然對於普通用户來説可能並不明顯，但在過去十年左右的時間裏，Linux 文件系統已經發生了顯著的變化，這使它們能夠更好對抗損壞和性能問題。</p><p>如今大多數 Linux 系統使用名為 ext4 的文件系統。 “ext” 代表“<ruby>擴展<rt>extended</rt></ruby>”，“4” 表示這是此文件系統的第 4 代。隨着時間的推移添加的功能包括：能夠提供越來越大的文件系統（目前大到 1,000,000 TiB）和更大的文件（高達 16 TiB），更抗系統崩潰，更少碎片（將單個文件分散為存在多個位置的塊）以提高性能。</p><p>ext4 文件系統還帶來了對性能、可伸縮性和容量的其他改進。實現了元數據和日誌校驗和以增強可靠性。時間戳現在可以跟蹤納秒級變化，以便更好地對文件打戳（例如，文件創建和最後更新時間）。並且，在時間戳字段中增加了兩個位，2038 年的問題（存儲日期/時間的字段將從最大值翻轉到零）已被推遲到了 400 多年之後（到 2446）。</p><h3 id="文件系統類型" tabindex="-1">文件系統類型 <a class="header-anchor" href="#文件系統類型" aria-label="Permalink to “文件系統類型”">​</a></h3><p>要確定 Linux 系統上文件系統的類型，請使用 <code>df</code> 命令。下面顯示的命令中的 <code>-T</code> 選項顯示文件系統類型。 <code>-h</code> 顯示“易讀的”磁盤大小。換句話説，調整報告的單位（如 M 和 G），使人們更好地理解。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -hT | head -10</span></span>
<span class="line"><span>Filesystem     Type      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>udev           devtmpfs  2.9G     0  2.9G   0% /dev</span></span>
<span class="line"><span>tmpfs          tmpfs     596M  1.5M  595M   1% /run</span></span>
<span class="line"><span>/dev/sda1      ext4      110G   50G   55G  48% /</span></span>
<span class="line"><span>/dev/sdb2      ext4      457G  642M  434G   1% /apps</span></span>
<span class="line"><span>tmpfs          tmpfs     3.0G     0  3.0G   0% /dev/shm</span></span>
<span class="line"><span>tmpfs          tmpfs     5.0M  4.0K  5.0M   1% /run/lock</span></span>
<span class="line"><span>tmpfs          tmpfs     3.0G     0  3.0G   0% /sys/fs/cgroup</span></span>
<span class="line"><span>/dev/loop0     squashfs   89M   89M     0 100% /snap/core/7270</span></span>
<span class="line"><span>/dev/loop2     squashfs  142M  142M     0 100% /snap/hexchat/42</span></span></code></pre></div><p>請注意，<code>/</code>（根）和 <code>/apps</code> 的文件系統都是 ext4，而 <code>/dev</code> 是 devtmpfs 文件系統（一個由內核填充的自動化設備節點）。其他的文件系統顯示為 tmpfs（駐留在內存和/或交換分區中的臨時文件系統）和 squashfs（只讀壓縮文件系統的文件系統，用於快照包）。</p><p>還有 proc 文件系統，用於存儲正在運行的進程的信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -T /proc</span></span>
<span class="line"><span>Filesystem     Type 1K-blocks  Used Available Use% Mounted on</span></span>
<span class="line"><span>proc           proc         0     0         0    - /proc</span></span></code></pre></div><p>當你在整個文件系統中游覽時，可能會遇到許多其他文件系統類型。例如，當你移動到目錄中並想了解它的文件系統時，可以運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /dev/mqueue; df -T .</span></span>
<span class="line"><span>Filesystem     Type   1K-blocks  Used Available Use% Mounted on</span></span>
<span class="line"><span>mqueue         mqueue         0     0         0    - /dev/mqueue</span></span>
<span class="line"><span>$ cd /sys; df -T .</span></span>
<span class="line"><span>Filesystem     Type  1K-blocks  Used Available Use% Mounted on</span></span>
<span class="line"><span>sysfs          sysfs         0     0         0    - /sys</span></span>
<span class="line"><span>$ cd /sys/kernel/security; df -T .</span></span>
<span class="line"><span>Filesystem     Type       1K-blocks  Used Available Use% Mounted on</span></span>
<span class="line"><span>securityfs     securityfs         0     0         0    - /sys/kernel/security</span></span></code></pre></div><p>與其他 Linux 命令一樣，這裏的 <code>.</code> 代表整個文件系統的當前位置。</p><p>這些和其他獨特的文件系統提供了一些特殊功能。例如，securityfs 提供支持安全模組的文件系統。</p><p>Linux 文件系統需要能夠抵抗損壞，能夠承受系統崩潰並提供快速、可靠的性能。由幾代 ext 文件系統和新一代專用文件系統提供的改進使 Linux 系統更易於管理和更可靠。</p><hr>`,18)),p("p",null,[s[1]||(s[1]=e("via: ",-1)),a(n,{href:"https://www.networkworld.com/article/3432990/a-guided-tour-of-linux-file-system-types.html"},{default:t(()=>[...s[0]||(s[0]=[e("https://www.networkworld.com/article/3432990/a-guided-tour-of-linux-file-system-types.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=e("作者：",-1)),a(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...s[2]||(s[2]=[e("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const T=i(u,[["render",f]]);export{b as __pageData,T as default};
